        run("export adapter preserves Shadertoy BO3 runtime parity", [&]() -> QString
        {
            const QString paintLike = QString::fromUtf8(R"HLSL(
#include "postfx/postfx_common.h"
Texture2D<float4> iChannel2 : register(t4);
Texture2D<float4> iChannel1 : register(t3);
Texture2D<float4> iChannel0 : register(t2);
SamplerState glslSampler2 : register(s4);
SamplerState glslSampler1 : register(s3);
SamplerState glslSampler0 : register(s2);
#define iResolution (float3(PostFx_GetRenderTargetSize().xy, 1.0))
#define GLSL_TEXTURE_LEVEL_S(tex,samp,uv,lod) tex.SampleLevel(samp,(uv),(lod))
int2 GLSL_TEXTURE_SIZE(Texture2D<float4> tex, int lod) { uint w=1,h=1,l=1; tex.GetDimensions((uint)lod,w,h,l); return int2(w,h); }
float2 GLSL_VEC2_S(float x) { return float2(x,x); }
#define Res0 GLSL_VEC2_S((float)(GLSL_TEXTURE_SIZE(iChannel0, 0)))
struct PS_INPUT { float4 position:SV_Position; float2 texcoord:TEXCOORD0; };
float4 ps_main(PS_INPUT input):SV_Target
{
    float2 fragCoord = float2(input.position.x, iResolution.y - input.position.y);
    float2 uv = fragCoord / Res0;
    float4 fragColor = GLSL_TEXTURE_LEVEL_S(iChannel0, glslSampler0, uv, 0.0) +
                       GLSL_TEXTURE_LEVEL_S(iChannel2, glslSampler2, uv, 0.0) * 0.01 +
                       GLSL_TEXTURE_LEVEL_S(iChannel1, glslSampler1, uv, 0.0) * 0.01;
    return fragColor;
}
)HLSL");
            bo3::PackageAdapterRequest request;
            request.target = bo3::PackageTarget::PostFx;
            request.configuration = bo3::PackageConfiguration::Runtime;
            request.source = paintLike;
            request.sourceFileName = "sv_paint.hlsl";
            request.mappingOverrides["iChannel0"] = "resolvedScene";
            request.mappingOverrides["iChannel1"] = "materialImage";
            request.mappingOverrides["iChannel2"] = "resolvedScene";
            const bo3::PackageAdapterResult adapted = bo3::adaptShaderPackage(request);
            if(adapted.confidence != bo3::AutomationConfidence::Auto || adapted.diagnostics.hasErrors())
                return adapted.diagnostics.toText();
            if(adapted.adaptedSource.contains("GLSL_VEC2_S((float)(int2(iResolution.xy)))"))
                return "resolvedScene size adaptation still collapses height into width";
            if(!adapted.adaptedSource.contains("#define Res0 (iResolution.xy)"))
                return "resolvedScene scalar-splat textureSize was not collapsed to iResolution.xy";
            if(!adapted.adaptedSource.contains("BO3_SCENE_TEXTURE_LEVEL_S(iChannel0,") ||
               !adapted.adaptedSource.contains("BO3_SCENE_TEXTURE_LEVEL_S(iChannel2,"))
                return "resolvedScene channel orientation/color bridge was not exported";
            if(adapted.adaptedSource.contains("BO3_SCENE_TEXTURE_LEVEL_S(iChannel1,"))
                return "auxiliary noise channel was incorrectly treated as resolvedScene";
            if(!adapted.adaptedSource.contains("PostFx_DenormalizeColor(fragColor.rgb)"))
                return "final BO3 PostFX output denormalization was not exported";
            return {};
        });

        run("optimized PostFX resource stripping is detectable", [&]() -> QString
        {
            auto compileAndReflect = [&](const QByteArray& hlsl, QSet<QString>& textures, QSet<QString>& samplers) -> QString
            {
                ComPtr<ID3DBlob> bytecode;
                ComPtr<ID3DBlob> errorBlob;
                const HRESULT hr = D3DCompile(
                    hlsl.constData(), static_cast<SIZE_T>(hlsl.size()), "postfx_resource_reflection_regression.hlsl",
                    nullptr, nullptr, "ps_main", "ps_5_0",
                    D3DCOMPILE_ENABLE_STRICTNESS | D3DCOMPILE_OPTIMIZATION_LEVEL3, 0,
                    bytecode.GetAddressOf(), errorBlob.GetAddressOf());
                if(FAILED(hr))
                {
                    if(errorBlob)
                        return QString::fromUtf8(static_cast<const char*>(errorBlob->GetBufferPointer()),
                                                 static_cast<int>(errorBlob->GetBufferSize()));
                    return "D3DCompile failed without diagnostics";
                }

                ComPtr<ID3D11ShaderReflection> reflection;
                if(FAILED(D3DReflect(bytecode->GetBufferPointer(), bytecode->GetBufferSize(),
                                     IID_PPV_ARGS(reflection.GetAddressOf()))))
                    return "D3DReflect failed";
                D3D11_SHADER_DESC desc{};
                if(FAILED(reflection->GetDesc(&desc))) return "reflection GetDesc failed";
                for(UINT i = 0; i < desc.BoundResources; ++i)
                {
                    D3D11_SHADER_INPUT_BIND_DESC bind{};
                    if(FAILED(reflection->GetResourceBindingDesc(i, &bind)) || !bind.Name) continue;
                    const QString name = QString::fromUtf8(bind.Name);
                    if(bind.Type == D3D_SIT_TEXTURE) textures.insert(name);
                    if(bind.Type == D3D_SIT_SAMPLER) samplers.insert(name);
                }
                return {};
            };

            const QByteArray stripped = R"HLSL(
Texture2D<float4> frameBuffer : register(t0);
SamplerState bilinearClampler : register(s1);
float4 ps_main(float4 p : SV_POSITION) : SV_TARGET0 { return float4(0.25,0.5,0.75,1.0); }
)HLSL";
            QSet<QString> strippedTextures, strippedSamplers;
            QString problem = compileAndReflect(stripped, strippedTextures, strippedSamplers);
            if(!problem.isEmpty()) return problem;
            if(strippedTextures.contains("frameBuffer") || strippedSamplers.contains("bilinearClampler"))
                return "FXC did not strip the intentionally unused probe resources; regression cannot exercise linker-parity detection";

            const QByteArray kept = R"HLSL(
Texture2D<float4> frameBuffer : register(t0);
SamplerState bilinearClampler : register(s1);
float4 ps_main(float4 p : SV_POSITION) : SV_TARGET0
{
    float a = frameBuffer.Sample(bilinearClampler, float2(0.5,0.5)).a;
    return float4(0.25,0.5,0.75,a);
}
)HLSL";
            QSet<QString> keptTextures, keptSamplers;
            problem = compileAndReflect(kept, keptTextures, keptSamplers);
            if(!problem.isEmpty()) return problem;
            if(!keptTextures.contains("frameBuffer") || !keptSamplers.contains("bilinearClampler"))
                return "keep-alive sample did not preserve frameBuffer + bilinearClampler in optimized reflection";
            return {};
        });

