        run("bundled sample is an authored BO3 package", [&]() -> QString
        {
            QString shaderPath = runtimePath("shaders/sample_bo3_postfx.hlsl");
            QString techsetPath = companionTechsetPathForShader(shaderPath);
            const QString sourceTreeShader = QDir::current().filePath("shaders/sample_bo3_postfx.hlsl");
            const QString sourceTreeTechset = companionTechsetPathForShader(sourceTreeShader);
            if(techsetPath.isEmpty() && !sourceTreeTechset.isEmpty())
            {
                shaderPath = sourceTreeShader;
                techsetPath = sourceTreeTechset;
            }
            if(shaderPath.isEmpty() || techsetPath.isEmpty())
                return "bundled HLSL/companion techset pair was not found";
            QFile shaderFile(shaderPath), techsetFile(techsetPath);
            if(!shaderFile.open(QIODevice::ReadOnly | QIODevice::Text) ||
               !techsetFile.open(QIODevice::ReadOnly | QIODevice::Text))
                return "bundled package files could not be opened";
            const QString shader = QString::fromUtf8(shaderFile.readAll());
            const QString techset = QString::fromUtf8(techsetFile.readAll());
            if(!shader.contains("GetTime()") || !shader.contains("PostFx_GetRenderTargetSize()"))
                return "sample still depends on undeclared preview-only time/target globals";

            bo3::TechsetParseOptions runtimeOptions;
            runtimeOptions.configuration = bo3::PackageConfiguration::Runtime;
            const bo3::TechsetParseResult parsed = bo3::parseTechset(
                techset, QFileInfo(techsetPath).fileName(), runtimeOptions);
            if(parsed.validation.hasErrors()) return parsed.validation.toText();
            const bo3::TechniqueResolutionResult resolved = bo3::resolveTechnique(parsed.model, "lit");
            if(!resolved.found) return resolved.validation.toText();
            QMap<QString, QString> codeTextures;
            for(const bo3::StageResourceBindingModel& binding : resolved.technique.pixelShader.resourceBindings)
                if(binding.valueKind == bo3::BindingValueKind::CodeTexture)
                    codeTextures[binding.parameterName] = binding.valueName;
            if(codeTextures.value("frameBuffer") != "resolvedScene" ||
               codeTextures.value("DepthSampler") != "floatZ")
                return "runtime CodeTexture bindings do not expose resolvedScene + floatZ";
            if(!parsed.model.findParameter("frameBufferSampler") ||
               !parsed.model.findParameter("DepthSamplerState"))
                return "sample sampler parameters are missing from the authored techset";

            bo3::ValidationResult validation = validatePostFxPackageForBo3(
                shader, techset, QFileInfo(shaderPath).fileName(), bo3::PackageConfiguration::Runtime);
            validation.append(validatePostFxPackageForBo3(
                shader, techset, QFileInfo(shaderPath).fileName(), bo3::PackageConfiguration::Toolsgfx));
            return validation.status() == bo3::CompatibilityStatus::Pass
                ? QString() : validation.toText();
        });

