        setTabPosition(Qt::BottomDockWidgetArea, QTabWidget::North);
        // The preview owns the right side while one shared bottom tab strip owns
        // the utility area across the full window. This keeps the editor/preview
        // dominant and prevents secondary tools from competing for vertical space.
        // Bottom tools own both lower corners so Console / Values / Parameters /
        // Textures / Performance form one predictable tab strip across the window.
        setCorner(Qt::BottomLeftCorner, Qt::BottomDockWidgetArea);
