        environmentPathLabel_->setToolTip("Drop a 2:1 equirectangular EXR/PNG/JPG/TIFF sky/environment image here, or use Load Sky.");
        envRow->addWidget(environmentPathLabel_, 1);
        auto* loadEnvironment = new QPushButton("Load Sky...");
        auto* clearEnvironment = new QPushButton("Clear Sky");
        envRow->addWidget(loadEnvironment);
