        environmentLightingCheck_ = new QCheckBox("Environment affects lighting");
        environmentLightingCheck_->setChecked(true);
        environmentLightingCheck_->setToolTip("Uses the loaded sky image to tint ambient light and the fake sun color.");
        outer->addWidget(environmentLightingCheck_);

        auto* bgRow = new QHBoxLayout();
        backgroundColorButton_ = new QPushButton("Background: Black");
