        connect(groundCheck_, &QCheckBox::toggled, this, [this](bool enabled){ if(preview_) preview_->renderer().SetGroundEnabled(enabled); });
        connect(wireframeCheck_, &QCheckBox::toggled, this, [this](bool enabled){ if(preview_) preview_->renderer().SetWireframe(enabled); });
        connect(loadEnvironment, &QPushButton::clicked, this, [this]{ loadEnvironmentTexture(); });
