    void showFindBar()
    {
        findBar_->setVisible(true);
        QString selected = editor_->textCursor().selectedText();
        if (!selected.isEmpty() && !selected.contains(QChar::ParagraphSeparator)) findEdit_->setText(selected);
        findEdit_->setFocus(); findEdit_->selectAll();
        rebuildSearchHighlights(true);
    }

    void closeFindBar()
    {
        findBar_->setVisible(false);
        editor_->setSearchSelections({});
        editor_->setFocus();
    }

    void rebuildSearchHighlights(bool moveToFirst)
    {
        searchMatches_.clear();
        const QString needle = findEdit_->text();
        if (needle.isEmpty())
        {
            editor_->setSearchSelections({}); findCount_->setText("0/0"); return;
        }
        const QString haystack = editor_->toPlainText();
        const int needleLength = static_cast<int>(needle.size());
        int pos = 0;
        while ((pos = haystack.indexOf(needle, pos, Qt::CaseInsensitive)) >= 0)
        {
            searchMatches_.push_back({pos, needleLength});
            pos += std::max(1, needleLength);
            if (searchMatches_.size() >= 5000) break;
        }
        if (searchMatches_.isEmpty())
        {
            currentSearch_ = -1;
            editor_->setSearchSelections({}); findCount_->setText("0/0"); return;
        }
        if (moveToFirst || currentSearch_ < 0 || currentSearch_ >= searchMatches_.size())
        {
            const int cursorPos = editor_->textCursor().selectionStart();
            currentSearch_ = 0;
            for (int i = 0; i < searchMatches_.size(); ++i) if (searchMatches_[i].first >= cursorPos) { currentSearch_ = i; break; }
        }
        updateSearchSelection();
    }

    void findNext(bool backwards)
    {
        if (!findBar_->isVisible()) showFindBar();
        if (searchMatches_.isEmpty()) { rebuildSearchHighlights(true); if (searchMatches_.isEmpty()) return; }
        currentSearch_ += backwards ? -1 : 1;
        if (currentSearch_ < 0) currentSearch_ = searchMatches_.size() - 1;
        if (currentSearch_ >= searchMatches_.size()) currentSearch_ = 0;
        updateSearchSelection();
    }

    void updateSearchSelection()
    {
        QList<QTextEdit::ExtraSelection> selections;
        for (int i = 0; i < searchMatches_.size(); ++i)
        {
            QTextCursor cursor(editor_->document());
            cursor.setPosition(searchMatches_[i].first);
            cursor.setPosition(searchMatches_[i].first + searchMatches_[i].second, QTextCursor::KeepAnchor);
            QTextEdit::ExtraSelection sel;
            sel.cursor = cursor;
            sel.format.setBackground(i == currentSearch_ ? QColor("#D18616") : QColor("#515C6A"));
            sel.format.setForeground(QColor("#FFFFFF"));
            selections.push_back(sel);
        }
        editor_->setSearchSelections(selections);
        if (currentSearch_ >= 0 && currentSearch_ < searchMatches_.size())
        {
            QTextCursor cursor(editor_->document());
            cursor.setPosition(searchMatches_[currentSearch_].first);
            cursor.setPosition(searchMatches_[currentSearch_].first + searchMatches_[currentSearch_].second, QTextCursor::KeepAnchor);
            editor_->setTextCursor(cursor);
            editor_->centerCursor();
            findCount_->setText(QString("%1/%2").arg(currentSearch_ + 1).arg(searchMatches_.size()));
        }
    }

    void refreshScriptVectorControls()
    {
        refreshingVectors_ = true;
        const auto& detected = preview_->renderer().DetectedScriptVectors();
        int detectedCount = 0;
        for (int v = 0; v < 8; ++v)
        {
            const bool enabled = detected[static_cast<size_t>(v)];
            if (enabled) ++detectedCount;
            vectorLabels_[v]->setEnabled(enabled);
            const auto values = preview_->renderer().GetEffectiveScriptVector(v);
            for (int c = 0; c < 4; ++c)
            {
                QSignalBlocker blocker(vectorBoxes_[v][c]);
                vectorBoxes_[v][c]->setEnabled(enabled);
                vectorBoxes_[v][c]->setValue(values[static_cast<size_t>(c)]);
            }
        }
        vectorInfo_->setText(detectedCount ? QString("Detected %1 script vector%2 in the compiled pixel shader.").arg(detectedCount).arg(detectedCount == 1 ? "" : "s")
                                           : "No scriptVector0-7 variables were reflected from this shader.");
        refreshingVectors_ = false;
    }

    bool readLastWriteTime()
    {
        if (shaderPath_.isEmpty()) return false;
        std::error_code ec;
        auto time = fs::last_write_time(fs::path(shaderPath_.toStdWString()), ec);
        if (ec) return false;
        lastWriteTime_ = time;
        return true;
    }

    void checkWatchedFile()
    {
        if (!watchFile_->isChecked() || shaderPath_.isEmpty() || modified_) return;
        std::error_code ec;
        auto current = fs::last_write_time(fs::path(shaderPath_.toStdWString()), ec);
        if (ec) return;
        if (!lastWriteTimeValid_) { lastWriteTime_ = current; lastWriteTimeValid_ = true; return; }
        if (current != lastWriteTime_)
        {
            lastWriteTime_ = current;
            QFile file(shaderPath_);
            if (!file.open(QIODevice::ReadOnly)) return;
            const CodeEditor::ViewState viewState = editor_->captureViewState();
            loadingText_ = true;
            editor_->setPlainText(QString::fromUtf8(file.readAll()));
            loadingText_ = false;
            editor_->restoreViewState(viewState);
            modified_ = false;
            compileEditor();
            statusBar()->showMessage("Reloaded shader changed on disk", 2500);
        }
    }

    void updateTitle()
    {
        if(beginnerProjectActive_ && beginnerUiMode_)
        {
            const QString name = beginnerProjectPath_.isEmpty()
                ? beginnerProject_.name
                : QFileInfo(beginnerProjectPath_).fileName();
            setWindowTitle(QString("BO3 Shader Studio %1 - %2%3")
                .arg(displayVersion_, name, beginnerProjectModified_ ? " *" : ""));
            return;
        }
        QString name;
        if(!shaderPath_.isEmpty()) name = QFileInfo(shaderPath_).fileName();
        else if(beginnerProjectActive_) name = beginnerProject_.name + " — Generated HLSL";
        else name = "Untitled";
        setWindowTitle(QString("BO3 Shader Studio %1 - %2%3").arg(displayVersion_).arg(name).arg(modified_ ? " *" : ""));
    }

